#include <iostream>
#include <string>
using namespace std;

struct Record {
    string name;
    int amount;
};

void addRecord(Record book[], int& count, string name, int amount) {
    book[count].name = name;
    book[count].amount = amount;
    count = count + 1;
}

int main() {
    Record book[8];
    int count = 0;

    string n1;
    string n2;
    int a1 = 0;
    int a2 = 0;
    cin >> n1 >> a1 >> n2 >> a2;

    addRecord(book, count, n1, a1);
    addRecord(book, count, n2, a2);

    for (int i = 0; i < count; i++) {
        cout << book[i].name << " " << book[i].amount << endl;
    }
    cout << "一共记了 " << count << " 笔喵" << endl;
    return 0;
}
